Section CselsW.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).
Local Open Scope Z_scope.

(* [comment removed for export] *)
Definition cs_blk (C : lctx) (A A' : AS) (pn : Z * Z) : Prop :=
  live A' (Z_to_bv 64 (fst pn)) = Some (snd pn) /\ live A (Z_to_bv 64 (fst pn)) = None /\ live (c_A0 C) (Z_to_bv 64 (fst pn)) = None /\ 0 <= fst pn < 2 ^ 64.
(* [comment removed for export] *)
Definition cs_cell (m : word -> option byte) (c : Z * nat * Z) : Prop :=
  rdn SEGS m (Z_to_bv 64 (fst (fst c))) (snd (fst c)) = Some (Z_to_le_bytes (snd (fst c)) (snd c)).
(* [comment removed for export] *)
Fixpoint cs_mk (base stride : Z) (n : nat) (i0 : Z) (vals : list Z) : list (Z * nat * Z) :=
  match vals with [] => [] | v :: t => (base + stride * i0, n, v) :: cs_mk base stride n (i0 + 1) t end.
Definition cs_rows (rows : list Z) (i : Z) : Z := nth (Z.to_nat i) rows 0.
Definition cs_tab (tab : list (list Z)) (i j : Z) : Z := nth (Z.to_nat j) (nth (Z.to_nat i) tab []) 0.
Definition cs_sv (sy sx cy cx arr : Z) (rows : list Z) : selv := SELV sy sx cy cx arr 0 (cs_rows rows).
Definition cs_words (sel arr : Z) (rows : list Z) : list word := map (Z_to_bv 64) (sel :: arr :: rows).
Definition cs_sel_facts (C : lctx) (A A' : AS) (m' : word -> option byte) (sel arr sy sx cy cx : Z) (rows : list Z) (tab : list (list Z)) : Prop :=
  Forall (cs_blk C A A') ((sel, 32) :: (arr, 8 * sy) :: map (fun r => (r, 4 * sx)) rows) /\
  Forall (cs_cell m') [(sel + 0, 4%nat, sy); (sel + 4, 4%nat, sx); (sel + 8, 4%nat, cy); (sel + 12, 4%nat, cx); (sel + 16, 8%nat, arr); (sel + 24, 8%nat, 0)] /\
  Forall (cs_cell m') (cs_mk arr 8 8%nat 0 rows) /\
  Forall2 (fun r vals => Forall (cs_cell m') (cs_mk r 4 4%nat 0 vals)) rows tab.
Definition cs_tab_ok (sx : Z) (tab : list (list Z)) : bool :=
  forallb (fun vals => (Z.of_nat (length vals) =? sx) && forallb (fun v => (0 <=? v) && (v <? 2 ^ 31)) vals) tab.

