Lemma cs_sel_of : forall C A A' m' md' (sel arr sy sx cy cx : Z) (rows : list Z) (tab : list (list Z)),
  Cok C -> W C A' m' md' ->
  cs_sel_facts C A A' m' sel arr sy sx cy cx rows tab ->
  List.NoDup (cs_words sel arr rows) ->
  Z.of_nat (length rows) = sy -> 1 <= sy <= 10000 -> 1 <= sx <= 10000 -> 0 <= cy < 2 ^ 32 -> 0 <= cx < 2 ^ 32 ->
  cs_tab_ok sx tab = true ->
  sel_at (alloc_top (c_vm C)) A' m' sel (cs_sv sy sx cy cx arr rows) /\ sel_cont m' (cs_sv sy sx cy cx arr rows) (cs_tab tab) /\
  (forall p, sel_blk sel (cs_sv sy sx cy cx arr rows) p ->
     In (Z_to_bv 64 p) (cs_words sel arr rows) /\ live A (Z_to_bv 64 p) = None /\ live (c_A0 C) (Z_to_bv 64 p) = None) /\
